import React, { useState, useEffect } from 'react';

function TrustedDevices() {
  const [devices, setDevices] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Fetch registered devices
    const fetchDevices = async () => {
      try {
        const response = await fetch('http://localhost:3001/api/device-info');
        if (response.ok) {
          const data = await response.json();
          setDevices([data]); // Current device
        }
      } catch (error) {
        console.error('Failed to fetch devices:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchDevices();
  }, []);

  return (
    <div className="trusted-devices-container" style={{ padding: '20px' }}>
      <h2>📱 Trusted Devices</h2>
      <p>Manage your registered and trusted devices.</p>
      
      {loading ? (
        <p>Loading devices...</p>
      ) : (
        <div style={{ marginTop: '20px' }}>
          {devices.length === 0 ? (
            <p>No trusted devices registered yet.</p>
          ) : (
            devices.map((device, index) => (
              <div 
                key={index}
                style={{ 
                  padding: '16px', 
                  background: '#1a1a2e', 
                  borderRadius: '12px',
                  marginBottom: '12px',
                  border: '1px solid #333'
                }}
              >
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <div>
                    <h3 style={{ margin: '0 0 8px 0', color: '#4ecdc4' }}>
                      {device.browser || 'Unknown Browser'}
                    </h3>
                    <p style={{ margin: 0, color: '#888', fontSize: '14px' }}>
                      {device.os || 'Unknown OS'} • {device.device || 'Desktop'}
                    </p>
                  </div>
                  <span style={{ 
                    padding: '4px 12px', 
                    background: '#2ecc7133', 
                    color: '#2ecc71',
                    borderRadius: '20px',
                    fontSize: '12px'
                  }}>
                    ✓ Trusted
                  </span>
                </div>
                {device.fingerprint && (
                  <p style={{ 
                    margin: '12px 0 0 0', 
                    color: '#666', 
                    fontSize: '11px',
                    fontFamily: 'monospace'
                  }}>
                    ID: {device.fingerprint.substring(0, 16)}...
                  </p>
                )}
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
}

export default TrustedDevices;
